create extension if not exists pgcrypto;

create type public.verification_status as enum ('VERIFIED','PARTIALLY_VERIFIED','UNVERIFIED','NOT_FOUND','UNKNOWN');
create type public.count_scope as enum ('CITY','GLOBAL','UNKNOWN');
create type public.job_status as enum ('OPEN','CLOSED','UNKNOWN');
create type public.observation_status as enum ('NEW','PERSISTENT','REMOVED','UNKNOWN');
create type public.career_source_type as enum ('OFFICIAL_COMPANY','GREENHOUSE','LEVER','WORKABLE','WORKDAY','SUCCESSFACTORS','PHENOM','ZOHO_RECRUIT','SMARTRECRUITERS','ASHBY','ICIMS','TALEO','JOBVITE','OTHER_ATS','THIRD_PARTY','UNKNOWN');

create table public.companies (id uuid primary key default gen_random_uuid(), canonical_name text not null, description text, website text, industry text, company_type text, company_size text, founded_year integer check (founded_year between 1000 and 2100), headquarters text, funding_stage text, funding_amount numeric, latest_funding_date date, linkedin_url text, logo_url text, verification_status public.verification_status not null default 'UNKNOWN', original_verification_status text, source_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index companies_canonical_name_idx on public.companies (canonical_name);
create table public.company_aliases (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, alias text not null, alias_type text not null default 'ALIAS', notes text, created_at timestamptz not null default now(), unique(company_id, alias));
create table public.company_locations (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, city text, state text, country text default 'India', address text, source_url text, verification_status public.verification_status not null default 'UNKNOWN', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(company_id, city, state, country));
create table public.career_sources (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, source_type public.career_source_type not null default 'UNKNOWN', source_url text not null, source_name text, is_official boolean not null default false, verification_status public.verification_status not null default 'UNKNOWN', last_checked_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(company_id, source_url));
create table public.jobs (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, title text not null, normalized_title text not null, job_url text, location text, city text, state text, country text, experience_requirement text, employment_type text, work_mode text, description text, skills jsonb not null default '[]'::jsonb, education_requirement text, salary text, deadline date, source_url text, source_type public.career_source_type not null default 'UNKNOWN', verification_status public.verification_status not null default 'UNKNOWN', first_seen_at timestamptz not null default now(), last_seen_at timestamptz not null default now(), status public.job_status not null default 'UNKNOWN', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(company_id, normalized_title, job_url));
create index jobs_city_status_idx on public.jobs(city, status); create index jobs_company_idx on public.jobs(company_id);
create table public.job_observations (id uuid primary key default gen_random_uuid(), job_id uuid not null references public.jobs(id) on delete cascade, observed_at timestamptz not null default now(), title text not null, job_url text, location text, experience_requirement text, employment_type text, work_mode text, skills jsonb not null default '[]'::jsonb, source_url text, status public.observation_status not null default 'UNKNOWN', content_hash text, unique(job_id, observed_at, content_hash));
create table public.raw_imports (id uuid primary key default gen_random_uuid(), source_file text not null, city text, imported_at timestamptz not null default now(), row_count integer not null default 0, successful_rows integer not null default 0, failed_rows integer not null default 0, import_status text not null, metadata jsonb not null default '{}'::jsonb);
create table public.raw_import_errors (id uuid primary key default gen_random_uuid(), raw_import_id uuid not null references public.raw_imports(id) on delete cascade, source_row integer, message text not null, raw_row jsonb not null, created_at timestamptz not null default now());

alter table public.companies enable row level security; alter table public.company_aliases enable row level security; alter table public.company_locations enable row level security; alter table public.career_sources enable row level security; alter table public.jobs enable row level security; alter table public.job_observations enable row level security; alter table public.raw_imports enable row level security; alter table public.raw_import_errors enable row level security;
create policy "public can read companies" on public.companies for select using (true); create policy "public can read locations" on public.company_locations for select using (true); create policy "public can read career sources" on public.career_sources for select using (true); create policy "public can read jobs" on public.jobs for select using (true); create policy "public can read observations" on public.job_observations for select using (true); create policy "service role manages companies" on public.companies for all using (auth.role() = 'service_role') with check (auth.role() = 'service_role');
